-- lyric previews from LRCLIB (scripts/fetch-previews.mjs). Safe to re-run; never overwrites an existing preview.
alter table public.songs add column if not exists preview text check (char_length(preview) <= 200);

update public.songs set preview = v.preview from (values
('tinh suong khoi|phuong thanh', 'Đêm rót vào tim từng giọt lệ buồn Anh gióng vào đêm bao hồi chuông thánh Làm sao em quên bao ngày anh đến Giọt sương mong manh như giọt nước mắt Đọng trên mái tình ta Đêm đã tàn ch'),
('vay tra no tinh|phuong thanh', 'Đã bao lần em là người ra đi Đã bao lần em là người nói câu chia ly Để lại niềm đau cho một người ở lại Để lại niềm đau cho cuộc tình hóa dại Và em nghĩ điều đó bình thường thôi Đã'),
('tinh ca muon doi|phuong thanh', 'Tình yêu mới đến mới đến Là cơn gió cuốn gió cuốn Lòng như lá nhẹ tênh quá Gió cuốn đi hoài Tình yêu mới đến mới đến Là mây trắng trôi lênh đênh Lòng như gió Vờn theo áng mây trôi '),
('nguoi di ngoai pho|phuong thanh', 'Người đi đi ngoài phố, chiều nắng tắt bên sông Người đi đi ngoài phố, bóng dáng xưa mịt mù Thành ghế đá chiều công viên Ngày xưa, ngày xưa, ngày xưa đã hết rồi. Người đi đi ngoài p'),
('nguoi ve tu long dat|phuong thanh', 'Đêm nay nơi thâm sâu âm u Từng cơn gió lùa bên muôn cây reo vi vu Tựa như tiếng than vãn bao đau thương miên man Suốt trong đêm trường Trên không gian mênh mang mây đen Tìm nhau ké'),
('mua|phuong thanh', 'Vẫn biết Đêm không mang theo anh Biết tình mong manh Vẫn biết Đêm trôi qua không nhanh Xóa dấu tình anh Dù trong muôn ngàn tiếng reo hò Mình em trôi dài với mong chờ Dù đêm muôn ng'),
('mua xa|phuong thanh', 'Trời u ám mây vào thu gió mưa Chợt nghe lố tiếng ai Rì rào trong mưa lời biệt khúc ôi não nùng Giờ biệt ly tôi nhìn em xót xa Cuộc tình này mong chi kiếp tương phùng Chỉ còn trong '),
('dem nghe tieng mua|phuong thanh', 'Còn rơi mãi trên phiếm đàn Còn rơi mãi những tiếng buồn thở than Đã lâu rồi, nụ cười vắng trên môi Mưa rơi mưa rơi Còn rơi mãi nhớ thương ai Ướt bờ mi em dài Mưa rơi mưa rơi Còn là'),
('da khuc buon|phuong thanh', 'Tìm về cõi nhớ Ta còn nghe tiếng ai vọng về. Người em yêu hỡi Xin đừng quên dù trong phút giây. Và hãy nhớ xin nhớ 1 lời Rằng em vẫn yêu anh trọn đời. Nhưng cớ sao đôi mình Vẫn mãi'),
('khi man dem ruc sang|phuong thanh', 'Tựa như những ánh sao trời lượn bay ở khắp muôn nơi Màn đêm buông là lúc em cất lời Vì sao sáng nhất đêm nay là em giữa thế gian này Tại sao em lại đắm say như vậy? Có lẽ đi qua ba'),
('mot ngay xa xam|phuong thanh', 'Một ngày tàn nắng ấm Anh đi về bên kia Một ngày buồn chia ly Lấp đi giấc mộng trăm năm Một ngày lời xa xăm Em nhớ thương anh nhiều hơn Thôi những giận dỗi hờn ghen Còn trên tay Lời'),
('se khong tro lai|phuong thanh', 'Ngày tháng lúc trước sẽ không trở lại Lời hứa lúc trước sẽ không trở lại Chỉ còn trong em từng ngày bơ vơ Em muốn khóc muốn quên, quên đi một người Mà vẫn đâu đây còn vương chút hư'),
('noi dau ngot ngao|minh tuyet', 'Giờ đây em mất những phút yêu thương thuở nào Từ khi anh đến mang những yêu thương nồng trao Để khi em biết đã cách xa anh thật rồi Thì bao thương nhớ nay đã không bao giờ vơi Ôi b'),
('ca phe mot minh|minh tuyet', 'Sáng nay cà phê một mình Ngày buồn chợt mưa chợt mưa Nhớ anh bao nhiêu cho vừa Anh ơi anh ơi Sáng nay nghe mưa quanh mình Trời chợt lạnh như mùa đông Những cơn mưa rơi ơ hờ Rớt trê'),
('sau nay neu co yeu ai|minh tuyet', 'Sau này anh có yêu người mới Xin đừng mang gian dối Người ta không ngốc như là em ngốc Như là em thật lòng Sau này anh sẽ biết mùa đông Không lạnh như câu nói Dù em rất tốt nhưng t'),
('mai la nguoi den sau|minh tuyet', 'Vì sao em cứ mãi yêu người Nguyện yêu anh yêu mãi muôn đời Em đâu hay tình em đã đến sau Ngày hôm nay em muốn quên người Mà lòng em cứ nhớ thương hoài Anh yêu ơi em biết đi về đâu '),
('nu hong mong manh / tham goi ten anh|minh tuyet', 'Anh đem trao cho em nụ hồng Nụ hồng mong manh như sương mai trong gió Em nâng niu đem hoa về giữ trong hồn Mong sao hoa không phai sắc hương Nhưng bông hoa kia mau phai tàn Rụng tả'),
('giua doi minh|minh tuyet', 'Hey hey (yeh hey) Yeh yeh hey hey Khó nói trước ngày mai trên bước đời mình có ai còn ai chung tay Khó nói hơn nữa ngày mai dù mình chung đường mà lòng mình có yêu thương Ngước mắt'),
('yeu thuong mong manh|minh tuyet', 'Em, mình đã cho nhau nhiều hơn đã hứa Mà vì sao đôi khi anh thấy Yêu thương thật quá mong manh Người hỡi, tình mình tựa như Những áng mây trôi về đâu Vẫn mong cho mình mãi bên nhau'),
('ky vong sai lam|minh tuyet', 'Tôi đã đem nhớ thương đặt vào trong mình một chiếc gương Nhận ra có quá nhiều thứ khiến em lùi bước, giờ còn đây những vỡ tan Mình sẽ là của nhau hoặc là sẽ trở thành nỗi đau Biết '),
('xin loi anh|minh tuyet', 'Được ôm em trong tay Để em yêu nâng niu Thật là hạnh phúc đời anh Được say trong yêu thương Để quên bao phiền muộn Khi anh bên em cùng em Giờ em biết anh rất nhớ em Biết anh rất cầ'),
('ve day anh|minh tuyet', 'Và mùa đông lạnh lùng buốt giá Nỗi cô đơn riêng mình ta Và mùa đông một trời trắng xóa Cho tâm tư mong tháng ngày qua Đời còn nhiều nhung nhớ Cho dù tình mình đã lỡ Vẫn mong trông '),
('tham goi ten anh|minh tuyet', 'Gọi thầm tên anh lần cuối Con tim buốt nhói trong đêm sầu Còn lại gì khi tình qua mau Bao yêu dấu nay cũng theo gió trôi đi mịt mờ Đường về cô đơn lạnh giá Lang thang phố vắng tron'),
('sao anh ra di|minh tuyet', 'Còn lại gì hỡi anh Lời yêu rời xa trái tim Tình mình là thế sao Người đi lạnh câm một trái tim Không như nụ hoa khoe sắc hương thật nồng nàn Không như người ta đầy phấn son Không m'),
('anh muon em song sao?|minh tuyet', 'Bài hát nói về tình yêu Tình yêu của một người con gái ngu ngơ, dại khờ Cô yêu cô không cần biết đúng hay sai Không cần biết anh đến bên em vì yêu em Hay vì những lúc anh buồn, anh'),
('anh muon em song sao|minh tuyet', 'Bài hát nói về tình yêu Tình yêu của một người con gái ngu ngơ, dại khờ Cô yêu cô không cần biết đúng hay sai Không cần biết anh đến bên em vì yêu em Hay vì những lúc anh buồn, anh'),
('ben yeu xua anh van cho|minh tuyet', 'Rồi mây xám đã giăng trên cuộc tình ta Hoa xưa ngát hương bên hiên nắng tàn Đường tình sao tối tăm, không màu Người đem đến bao úa sầu Làm sao quên được anh, người yêu, tình yêu xa'),
('lk nguoi thu ba|minh tuyet', 'Tình mình như giấc mơ Bao phút giây thơ mộng nơi chốn này Tình nhẹ nhàng như áng mây Anh và em sẽ mãi như trời xanh Và nụ cười anh với ai, bên giấc mơ gia đình vang tiếng cười Rồi '),
('ngay em di|minh tuyet', 'Chiều hôm ấy trái tim em như vụn vỡ rồi Nhìn anh đi dưới cơn mưa em lại đau hơn Từng là tất cả của em Từng là thế giới bên em Vậy mà hôm nay chính em là người kết thúc Rồi mưa rơi '),
('de cho em khoc|minh tuyet', 'Có bao giờ anh nghĩ về em? Về những đắng caу em đã gánh chịu Từng ngàу trôi qua là những nỗi đau không phai nhoà Có bao giờ trong mơ vội vã Nhìn không thấу em anh đã đi tìm? Hay an'),
('tai vi chinh em|minh tuyet', 'Đến sau cuối khi đã chia tay nhau rồi Em mới biết rằng mình cần có anh Đến sau cuối khi hai ta bước đôi đường Em mới biết cuộc đời đầy bão giông Cần có anh cho qua đi đêm đông dài '),
('dung xa em dem nay|minh tuyet', 'Đừng xa em đêm nay khi bóng trăng qua hàng cây Đừng xa em đêm nay đêm rất dài Vòng tay em cô đơn Đêm khuya vắng nghe buồn hơn Con tim em khát khao yêu thương Đừng xa em đêm nay hãy'),
('mot doi em da yeu|minh tuyet', 'Em giấu thật sâu trong lòng Từng tiếng yêu riêng em chờ mong Dẫu biết tình này vô vọng Mà vẫn không sao quên đi hình bóng Em cố nhận ra một điều Dù từ rất lâu em không muốn hiểu Rằ'),
('hay ve day ben em|minh tuyet', 'Một mùa thu tàn úa lá vàng rơi khắp sân Mình em nơi đây cô đơn lặng lẽ Từ khi anh ra đi từng hàng cây trước sân Dường như cũng đã xác xơ đi nhiều Rồi mùa thu đi qua khi mùa đông đã'),
('em se la nguoi ra di|minh tuyet', 'Yêu nhau cho nhau từng nụ hôn nồng ấm ân ái hôm nào Còn đó bao dấu yêu nhưng đời ai nào ngờ Trôi như mây bay về tận cuối phương trời nao Bao đêm em mơ về ngày mai thầm ước trọn kiế'),
('tung yeu|minh tuyet', 'Có kí ức nào đẹp hơn ngày đôi ta bắt đầu Có đớn đau nào nặng hơn ngày mình xa nhau Có đôi mắt nào buồn hơn bờ mi em tuôn sầu Có đắng cay nào bằng anh vội vàng qua mau Người mà anh '),
('mot thuo yeu nguoi|minh tuyet', 'Cuộc tình dĩ vãng đã trôi đi vào quên lãng Kỷ niệm cũng chỉ là cơn sóng mơ hồ Nếu chúng mình đừng tiếc nuối ân tình Yêu chi cho tâm hồn mình thêm vỡ nát trong giấc mơ dài Một đời v'),
('sa mac tinh yeu|minh tuyet', 'Tình yêu anh ơi cút bắt trò chơi Em sẽ trốn khi anh đuổi tìm Tình sẽ theo thời gian nhạt nhòa phai, xin nhớ cho rằng Một lần yêu phải trăm lần khổ đau Giọt sương ban sớm lấp lánh t'),
('van muon yeu tron doi|minh tuyet', 'Mong manh tình yêu của tôi Nguyện dành trao về riêng người thôi Từng vần thơ đẹp như mây trời Mà sao không nói nên lời Thênh thang đường đi ngày sau Chợt nhận ra còn mơ về nhau Níu'),
('ke dung sau tinh yeu|minh tuyet', 'Lòng em ngây ngất vui, khi tình yêu đến hôm nào Rồi giông tố kéo qua em là chiếc bóng mà thôi Cố nén bao niềm đau nhưng nào có nén được đâu Cố bước đi thật mau nào có bước đi được '),
('lk da khong yeu thi thoi|minh tuyet', 'Đã không yêu thì thôi ta gặp nhau làm chi Thêm bao xót xa mình tôi anh ơi tình si Anh như áng mây trên trời và hoài xa xôi Dù xa nhưng trong tim tôi mình anh thôi Lời nói đầu môi a'),
('tinh bo vo|minh tuyet', 'Càng nhìn em Yêu em hơn và yêu em mãi Dù phút êm đềm xa xưa Nay đã đi vào quên lãng Trời vào thu Việt Nam buồn lắm anh ơi Mây tím đang dâng cao vời Mà tình thương chưa lên ngôi Ngà'),
('lau dai tinh ai|minh tuyet', 'Anh sẽ vì em làm thơ tình ái Anh sẽ gom mây kết thành lâu đài Đợi chờ một đêm trăng nào tới Đợi chiều vàng hôn lên làn tóc Đợi một lần không gian đổi mới Đón hai đứa chúng ta mà th'),
('nhung an tinh xua|minh tuyet', 'Em có biết từ khi em ra đi Trong lòng anh cả một trời hoang vắng Hãy nhớ, Lúc nào anh cũng mong em quay trở về Buồn lắm em hỡi những châu rơi trên mi người Em ra đi nơi đây còn tìn'),
('tan moi tinh dau|minh tuyet', 'Chiều hôm nay mình xa lìa nhau Hai trái tim đau chung niềm đau Đường cô liêu mình đi về đâu Rồi hai đứa ra sao ngày sau Làm sao biết anh sẽ không tiếc Làm sao biết anh sẽ quên hết '),
('roi xa nguoi yeu|minh tuyet', 'Van em cho anh chia tay người yêu Cho anh chia tay người thương Ôi dĩ vãng sao còn vương Xin cho quên đi bao nỗi ưu phiền Quên đi đôi mắt êm đềm Quên câu thơ trên môi mềm Xa rồi cu'),
('ket thuc nhu bao nguoi|minh tuyet', 'Cuối cùng thì người cũng đi rồi Chấm dứt những ngày vui Một lời xin lỗi xem như hết rồi Những tháng năm đã qua Những ước mơ chung của chúng ta Đành nhường lại người sau thiết tha C'),
('chi la khong cung nhau / tra nguoi ve tu do|minh tuyet', 'Là cơn mưa đã rơi lên từng nhớ quên một thời ấm êm Mặn đôi môi ướt đẫm con tim yếu mềm Mình ước tất cả sẽ như cơn mơ Chuyện tình yêu chưa từng tan vỡ Tỉnh giấc vẫn có ai kia đợi ch'),
('mua thu bien goi|minh tuyet', 'Mùa thu lắng nghe sóng vỗ từng cơn Hoàng hôn mênh mông chiếc lá vàng rơi Và anh bước đi trống vắng về đâu Sóng như gọi tên gào thét giữa đêm trường Hớ hớ hơ hờ hơ í ờ hớ hơ hờ hơ h'),
('noi buon gac tro|minh tuyet', 'Gác lạnh về khuya cơn gió lùa Trăng gầy nghiêng bóng cài song thưa Nhớ ai mà ánh đèn hiu hắt Lá vàng nhè nhẹ đưa Tưởng như bước lê hè phố Có người con gái buông tóc thề Thu về e ấp'),
('de nho mot thoi ta da yeu|minh tuyet', 'Hạnh phúc trong tầm với Đã không còn tới khi vắng em trong đời Tìm đến chân trời mới Vẫn thương một thời giờ đã xa ngàn khơi Ngày đó ta lầm lỡ bỏ mặc nhau hững hờ Để tiếng yêu rạn '),
('dem lao xao|minh tuyet', 'Đêm đông lao xao, đêm đông nhớ ai Đêm đông cô đơn vắng ai Cơn mưa lao xao, cơn mưa nhớ ai Ôi, hạt mưa rơi khóc thầm Anh đang nơi đâu, anh thương nhớ ai? Bao đêm cô đơn vắng anh Mon'),
('vang trang dem troi|minh tuyet', 'Vầng trăng đêm trôi xa sương trắng ôm trăng phai dần em ngồi đây Giọt lệ rơi trên sông ôi giống yêu thương dâng tràn khắp tim này Trào rơi niềm đau theo trăng ngồi chờ mong Lặng ng'),
('khi man dem ruc sang|minh tuyet', 'Tựa như những ánh sao trời lượn bay ở khắp muôn nơi Màn đêm buông là lúc em cất lời Vì sao sáng nhất đêm nay là em giữa thế gian này Tại sao em lại đắm say như vậy? Có lẽ đi qua ba'),
('neu mot ngay|minh tuyet', 'Nếu, nếu một ngày không có em Thì niềm cô đơn dài như năm tháng Như mùa thu chết không lá thu rơi Nếu, nếu ngày ấy mình đừng quen nhau Thì ngày nay có đâu buồn đau Những khi mình x'),
('goi ten ngay moi|minh tuyet', 'Một nụ hồng trên tay cuộc đời đẹp biết mấy. Lúc cô đơn đâu hay trong ta tình đầy Và nụ hồng trao đi người mỉm cười đôi khi. Những ưu tư lâu nay cũng qua. Người đâu biết tình đắng, '),
('em dung di|lam hung', 'Ngồi hát bài hát ngày xưa Gọi tên em trong đêm mưa buồn Lời hát với tất cả tình yêu anh gửi trao Mai đây em ra đi xa mãi Em sẽ chẳng đi đâu người ơi Ta bên nhau yêu mãi muôn đời Nh'),
('sau tim thiep hong|lam hung', 'Từ lúc quen nhau chưa nói một lời gì, tỏ tình ta mến nhau Nhiều đêm ngắm sao, mà ước duyên mình bền lâu, Suốt đời tình khắc sâu Nhớ thương đầy vơi, mộng thấy ai mỉm cười, Làn môi x'),
('ke da tinh|lam hung', 'Đêm lạnh buồn còn lại một mình tôi và tôi ngày xinh tươi cũng chỉ tôi và tôi Vì ngày xưa khi có em tôi không biết giữ gìn thì giờ này trách ai ngoài tôi đây Dĩ vãng buồn một mình m'),
('anh da hieu tinh em|lam hung', 'Còn ngại ngùng gì không dám yêu anh em ơi Dẫu đam mê đã vương đôi môi rồi Người còn ngại ngùng anh say đắm bao đóa hoa Để trái tim ai lạnh giá Khi trao con tim đến cho anh rất mong'),
('doan cuoi tinh yeu|lam hung', 'Còn khóc chi em thôi buồn chi em Dù có thương đau mình cũng xa rồi Ngày nao ta mơ chung đôi Ngờ đâu nay chia hai nơi Vui buồn ai biết trong đời Ðừng trách nghe em, xin hiểu cho anh'),
('vi mot nguoi|ung dai ve', 'Vì sao em nỡ nói với anh một câu: "Mai chúng ta không gặp"? Vì sao em cứ đánh thức một con tim đang mộng mơ? Vì sao con tim anh đây một lần nữa cố chấp như vậy? Vì sao con tim anh '),
('yeu mot nguoi phai chang lam loi|ung dai ve', 'Em có biết tim anh từ lâu đã khắc tên em? Em có biết em như cơn mưa đến nhanh vội tan? Anh không níu kéo được, đành chờ những cơn gió mang em đến đây. Tình yêu vẫn khiến bao người '),
('dung the nua|ung dai ve', 'Chớ nói với a mình đã ko còn hiểu nhau Chớ nói với a mình đã ko còn như ngày xưa Nếu muốn bước đi thì cứ quay mặt bước đi Nhưng chớ dày vò, buộc trái tim phải cố quên mình đã yêu T'),
('dem trang tinh yeu|ung dai ve', 'Chiều một mình trên phố năm xưa Lạc bước giữa đêm đông người Rồi một ngày em bỗng đi qua Sưởi ấm con tim lẻ loi Nụ cười và ánh mắt đam mê Trái tim đôi ta không rời Con thuyền không'),
('anh nho em nhieu|ung dai ve', 'Giờ đây trong lòng em còn yêu anh nhiều không Bởi vì bên cạnh em luôn có ai kia cười đùa Làm sao không giận đây làm sao im lặng đây Làm sao không hờn ghen khi đã yêu nhau Em ơi anh'),
('luon co mot vong tay|ngo kien huy', 'Khúc nhạc dịu êm Hòa vào đêm ngọt ngào hơn Với mưa phùn xa bước ngoài Ô kính nhỏ xa mơ Siết chặt vòng tay Để cảm thấy được gần thêm Mắt buồn này say đắm Cùng ngàn lời yêu Bước từng'),
('lien khuc: vang trang dem troi|ngo kien huy', 'Vầng trăng đêm trôi xa sương trắng ôm trăng phai dần em ngồi đây, Giọt lệ rơi trên sông ôi gió yêu thương dâng tràn khắp tim này Còn rơi niềm đau theo trăng hoài chờ mong, lặng ngh'),
('ngo kien huy la toi|ngo kien huy', 'Do you know me do you know me hah hah ah hah Do you know me do you know me my name is Kiến Huy Đêm nay mưa ngoài sân tôi thấy mưa như đang hiu quạnh Tôi muốn tiếng hát của tôi xóa '),
('loi chua noi|ngo kien huy', 'Những câu ân tình chưa nói Giờ bỗng tan như làn mây khói Khi tình yêu đã chết thật rồi Giờ làm gì cũng thế thôi Còn thiếu nhau bao lời xin lỗi Định nói ra nhưng rồi lại thôi Phút g'),
('nghi ngo|ngo kien huy', 'Hỡi người tình giận chi hoài Làm sao cho em hé môi cười Giận nhau chi cho sầu em nhé Lòng anh thêm đau buồn hơn Chớ giận hờn làm ưu sầu Hằn lên trên đôi mắt nhung huyền Tình yêu lu'),
('nguoi tinh oi mo gi|ngo kien huy', 'Uh, yeah-eh, yeah-eh Uh, yeah-eh, yeah-eh Oh-oh Bé ơi mơ gì thế em? Mà sao đôi mắt em trông vào xa xăm Cớ sao không nhìn thấy anh? Từ lâu đang ngắm em xinh như một thiên thần Ghét '),
('anh tin minh da cho nhau mot ky niem|ngo kien huy', 'Lần đầu tiên thấy em, chỉ muốn đến thật gần Chào em thôi, mong niềm vui hiện lên môi xinh Lần đầu tiên nắm tay, anh không tin ngón tay Từ em yêu lại vuốt ve, níu đôi bàn tay anh Ch'),
('xom nho don tet|ngo kien huy', 'Sáng nay trước hiên nhà Ồ cây mai của ông Tư đã Đã nở hoa, hoa nở vàng cả một góc sân (thiệt là đẹp à nha!) Thím Hai đi chợ về Người lom khom thịt heo dưa mắm Bánh chưng xanh đám t'),
('dinh menh ta gap nhau|ngo kien huy', 'Từng đêm anh mơ về em, mơ thấy em trở về Đến bên anh trong vòng tay ấm áp Có đôi khi anh rời xa lòng nhớ anh rất nhiều Nhớ tiếng nói anh bên tai dịu êm Định mệnh cho ta gặp nhau, a'),
('nho nho nho|ngo kien huy', 'Trong đêm một mình anh bước đi Tìm lại những ký ức đã xót xa đang làm cay khóe mi Khi đêm chỉ còn những giá băng Mặt tuyết trắng kéo đến khuất lấp bao nỗi niềm trong cõi lòng. Chợt'),
('yeu nham|ngo kien huy', 'Yêu Nhầm Người ta chỉ đến với nhau lúc buồn Người ta chỉ đến với nhau lúc cần Để rồi quay đi ơ thờ quay đi hững hờ Bao thoáng qua cuộc vui. Và em đã đến với tôi cũng vậy Và em đã k'),
('ngu ngoan tinh yeu|ngo kien huy', 'Người yêu của anh ơi! chúc em ngủ ngoan nhé em! Người yêu của anh ơi! Đêm nay nằm mơ giấc mơ dịu êm. Màn đêm của đôi ta từ nay có anh đưa em về qua lối vắng. Biết giờ mình sẽ mãi l'),
('ngan lan khac ten em|ngo kien huy', 'Đêm bỗng như Giọt nước mắt thấm mi cay Đường về ngày hôm nay Bỗng dưng ôi sao xa quá Anh nhớ em Người ơi, sao mới hôm qua Mà giờ chỉ mình anh lẻ loi lặng thầm lê bước Trong mưa? Ng'),
('chang the giu lay chang danh buong tay|ngo kien huy', 'Một mình ôm cô đơn trống vắng Còn bầu trời hôm nay không chút nắng Lạc vào quán quen nơi từng chứa những bình yên Ly cà phê hôm nay sao đắng hơn Trong lòng anh hôm nay có sóng gợn '),
('lac giua nhan gian|ngo kien huy', 'Ngoảnh mặt về phía cuối con đường ta đã qua Hoa rơi cho nỗi buồn tả tơi Ngày nào đôi chúng ta vẫn mộng mơ rất nhiều Mà nay mỗi đứa đã ôm riêng mình những điều Trong đôi mắt ấy cố g'),
('yeu va duoc yeu|ngo kien huy', 'Đời có nhiều lo âu, còn anh đi bên em cùng nhau Gần đấy rồi lại xa, vẫn là em trêu đùa anh mãi Lặng lẽ người yêu thương, để quan tâm luôn chở che Nhiều tiếng cười vui tươi từ khi n'),
('loi cua anh|ngo kien huy', 'Trả lại cho em đêm bình yên như ngày anh chưa hề đến Trả em khoảng trời không buồn đau, không còn suy tư về nhau Chuyện đã thế rồi, cũng đành thôi giờ đây mình như người dưng ngược'),
('ngoan xinh yeu cua anh dau roi|ngo kien huy', 'Ngoan xinh yêu của anh đâu rồi? Ngoan xinh yêu của anh đây rồi Cưng là báu vật trời đã ban Trong vòng quay tình yêu thế gian Ngoan xinh yêu của anh đây này Tương tư em trưa, sáng, '),
('nguoi nhu anh xung dang co don|ngo kien huy', 'Ánh sáng tắt đi, chẳng để lại thứ gì Cuối cùng, mọi cố gắng chỉ là vứt đi Tìm trong ký ức vẫn còn bờ vai, môi son Từng ở bên anh, từng nắm tay anh Trí nhớ khắc sâu ngày đôi ta mất '),
('sao em biet nguoi roi di khong buon|ngo kien huy', 'Người ta thường hay cho rằng Một khi chúng ta chia tay Người quay bước vì có hạnh phúc mới Còn bao nước mắt nằm trong tim người ở lại Nhưng không đúng cho tất cả em ơi Ngoại lệ đâu'),
('gia vo yeu|ngo kien huy', 'Đêm chia ly mưa buồn rơi héo hắt Bước chân anh trên đường khuya hoang vắng Bao yêu thương nơi này ta đã có Chính nơi đây chúng ta xa rời nhau Khi yêu nhau bây giờ anh mới biết Trái'),
('gia vo yeu...|ngo kien huy', 'TỔNG QUAN LỜI BÀI HÁT NGHE MỌI NGƯỜI CŨNG TÌM KIẾM Đêm chia ly, mưa buồn rơi héo hắt Bước chân anh trên đường khuya hoang vắng Bao yêu thương nơi này ta đã có Chính nơi đây chúng t'),
('quay lai lai yeu|ngo kien huy', 'Sau bao ngày xa cách Em bỗng hỏi anh giờ sống thế nào Đã có cô nào chưa nếu như là chưa Tại sao tin nhắn không trả lời Chỉ là dòng tin nhắn nhất thời Hỏi thăm chứ không phải là em '),
('yeu khong duong lui|ngo kien huy', 'Anh muốn thức dậy mỗi sớm yên bình Vẫn là em trong vòng tay (Vẫn là em trong vòng tay) Anh muốn những ngày nắng gió vơi đầy Vẫn thấy em tươi cười như vậy Vì yêu thương vẫn thế rất '),
('chi co the la yeu|ngo kien huy', 'Bao năm qua Vẫn thầm nghĩ về một người gần nhưng xa Bao năm qua Vẫn đang ôm thương nhớ ai Yêu một người chưa tìm ra lối Muốn làm thân nhưng chẳng dám nói Nên đành chôn tiếng yêu ấy'),
('hay tran trong nguoi thuong|ngo kien huy', 'Từng là tất cả, từng là một phần của nhau Thế sao giờ đây chẳng thể giữ bước chân em quay về Người thì cố chấp, người thì ngộ nhận cứ yêu Biết trong lòng em bây giờ đã khác Hạnh ph'),
('vo so lan tinh co|ngo kien huy', 'Vô số lần mình tình cờ lướt qua Chợt làm anh nhớ nhung, làm con tim bối rối Vô số lần mình lướt qua vô tình Dù có đi đến đâu cũng sẽ gặp lại nhau Từng ngày trôi khiến anh ngẩn ngơ,'),
('anh yeu em nhieu lam|isaac', 'Vì trái tim anh yêu em nhiều lắm Hạnh phúc bên em không thể nào quên Vì anh đã quá vô tâm người ơi Để hạnh phúc mới đánh rơi Bao năm trôi qua anh vẫn yêu em Dù chuyện tình mình giờ'),
('intro: ngay dau tien & anh se ve som thoi|isaac', 'Nhiều khi kiếm đâu cổ tích trên đời Thật là điều may mắn nếu như có người Cầm tay bước đi đến cuối con đường, bao giờ thì sẽ tới. Dẫu anh không là chàng hoàng tử mà em đắm say Chỉ '),
('cat em vao tam tu|isaac', 'Sẽ có lúc đớn đau từ tâm hồn Đêm mau qua đi, bình minh hé sáng sẽ ấm hơn Rồi nắm tay, níu vai đùa vui với chút nắng vàng Hạnh phúc ngày hôm qua anh giấu đi chỉ còn niềm đau Cất em '),
('yeu khong nghi phep|isaac', 'Bao nhiêu lâu để anh quên từng ngày Thời gian cứ thế trôi qua mau Nhưng hôm nay anh đã có một người Ở bên anh không lo sớm mai Và anh biết trái tim anh thật lòng Muốn mang em về nơ'),
('mot buoc yeu van dam dau|isaac', 'Một thế giới hư ảo nhưng thật ấm áp Em xuất hiện khiến những băng giá đời anh bỗng dần tan đi Cuộc đời anh đặt tên là muộn phiền nên làm sao dám mơ mình may mắn được trọn vẹn cùng '),
('noi ta cho em|will', 'Mình ta lê thê bước Ngược chiều gió đến với góc phố rất thân quen Tìm về đó với những nỗi nhớ không mang tên Mà giờ ta vẫn cồn cào nhớ đến (cồn cào nhớ đến) Chiều mang mây đen tới '),
('co em la du|will', 'Yêu quá nên như vậy Trời xanh cũng như màu hồng Trà sữa không cần đường phải không? Em ghé ngang qua đời Từ khi trót trao nụ cười Chắc phải đến 3 giờ 20 (chưa ngủ được) Không dây d'),
('em dang lam gi day|will', 'Này em, em đang làm gì đấy? Có thấy anh ngồi đây? Nhìn lên mái hiên nhà giờ đã xuống đêm Ngày mai khi em vừa tỉnh giấc Có nhớ câu hỏi thăm? Mình đã nói với nhau qua những đêm dài T'),
('tich tich tinh tang|will', 'Khúc hát Then Thần Sa (Then Thần Sa) Vang vọng va vách núi thành mảnh sáng lan xa Khúc hát Then Thần Sa (Then Thần Sa) Từ cổ xưa đã có mái đá Ngườm truyền lưu Truyện kể rằng bảy nà'),
('tan cung noi nho|will', 'Anh chơi vơi nơi góc phố quen mình từng Từng là tất cả Hôm ấy mây xanh ngát trời Cố giữ lấy chút ấm áp từ tay em Nhưng biết sao được, hôm nay mình chia tay Những tấm hình kỷ niệm c'),
('buon thi cu khoc di|will', 'Em có buồn, nếu anh để lại cây viết Dòng thư cuối sau bức màn? Nghe tiếng đàn, cất lên trong không gian thật yên lặng khiến anh ngỡ ngàng Chợt dòng chữ ấy đã phai nhanh vì mắt ướt '),
('thuong hai|khoi my', 'Người ta đã, đã tốt hơn em Người ta đã yêu anh, yêu rất chân thành Người ta đã cướp mất trái tim anh ra khỏi cuộc đời của em Ừ thì là định mệnh Người ta đã xứng đáng tốt hơn em Ngư'),
('de thuong|khoi my', 'Nắng ban mai rọi vào phòng khi em ngủ say Tình cờ làm cho em thức dậy Ô mình đã quá đôi mươi rồi Tóc loăn xoăn đầu bù rối nhưng em vẫn xinh Một mình soi gương em ngắm nhìn Cảm thấy'),
('chuc tet|khoi my', 'Năm mới Tết đến, rước hên vào nhà Quà cáp bao la, mọi nhà no đủ Vàng bạc đầy hũ, gia chủ phát tài Mùa xuân sang ta chúc nhau Bao ước muốn, bao hy vọng Cùng rủ nhau mau bay về Thắm '),
('dung ban tam|khoi my', 'Chỉ còn vài phút cuối, hãy nói với nhau Chỉ một câu trước khi biệt ly Niềm hạnh phúc đã vỡ, chỉ còn mỗi em đợi chờ Trong bơ vơ bóng anh xa mờ Tìm nơi đâu để thấy lúc ta gần nhau Nh'),
('khoc dem|khoi my', 'Dù xa nhau em vẫn mãi tin rằng một mai đây anh quay lại Vì em tin sâu thẳm trái tim anh còn yêu em Lời chia tay ngày xưa cũng không thể làm tim em quên được anh Chợt em đau, rồi đa'),
('gioi han|khoi my', 'Thôi, hay là quên, hay là xa Để ta không còn phải mong nhớ Thôi, không tìm nhau, không chờ nhau cho vơi nỗi đau Muộn phiền về bên em, ngày dài dường như mãi Cô đơn sao bất tận? Còn'),
('ho yeu ai mat roi|khoi my', 'Nhớ ánh mắt, nhớ đôi môi của em Nhớ đôi vai, hoàng hôn nơi ta từng quen Hà ha há ha ha hà ha há, giá như anh đừng gặp em Thì giờ anh vẫn cứ tin hai chữ tình duyên Em ra đi để lại n'),
('mua roi vao phong|khoi my', 'Cơn gió lùa qua ô cửa sổ Giọt nắng chiều sa trên mái hiên Em viết tình ca trên trang giấy Ôm chiếc đàn ghi ta, la, là Mưa bỗng ùa về trên căn gắc vắng Tí tách rơi từng giọt, từng g'),
('chuyen nang mua|khoi my', 'Sớm nay bầu trời còn đẹp trong xanh mát rượi Bỗng dưng chiều về mang cơn mưa lớn Giống như những chuyện tình vừa yên vui chút thôi Bỗng dưng có chuyện ghét nhau nữa rồi Những lúc b'),
('gui cho anh|khoi my', 'Những kỉ niệm ngày xưa vẫn còn Mãi mãi vương vấn ở nơi đây Vẫn còn đó những hàng cây Vẫn còn đó những câu chuyện ngày xưa mình bên nhau Khi tan trường về vẫn còn tay trong tay chun'),
('anh o dau|khoi my', 'Người về bên ấy có nhớ một người bên này Niềm vui bên anh, còn bên em là giọt nước mắt Em tiếc nuối những ngày qua Tiếc cho yêu thương ngày qua Đành xót xa nhìn anh quay bước ra đi'),
('tu ngay anh xa|khoi my', 'Cố gắng nắm lấy đôi tay này Nhưng nay phải buông xuống, trong lòng nghe giá buốt Giấc mơ qua theo một người rất xa Nơi bàn tay em vẫn nắm, không cho trôi đi những yêu thương Nắng t'),
('chuot yeu gao|khoi my', 'When that day I hear your voice I have some special feelings Let me always think I don''t wanna forget you I remember at the day You are always on my mind Eventhough I just can thin'),
('nguoi yeu cu|khoi my', 'Cuộc sống đâu lường trước điều gì Tình yêu có thể đến rồi đi Bàn tay dẫu đang nắm thật chặt Mà vẫn lạc nhau Còn nhớ trong ngày nắng nhạt nhòa Mình quay lưng về phía người kia Rồi b'),
('toi muon yeu mot nguoi|khoi my', 'Tôi muốn yêu người nào đó thật bình thường không sóng gió Chẳng lo lắng chẳng biết nuối tiếc thương đau là điều gì Tôi muốn buổi sáng thức giấc con tim lại thấy ấm êm vui mừng Vì t'),
('chuyen tinh mua|khoi my', 'Ngoài hiên mưa vẫn rơi từng cơn, chỉ còn nỗi đau nghe buồn hơn có những phút ấm áp chợt ghé qua Nhớ ngày nào mình sánh vai mà giờ tình đành nhạt phai, gió thét gào nát tan lòng anh'),
